<?php require_once __DIR__.'/../admin_catalog.php';require __DIR__.'/../staff_header.php'; ?>
<section class="admin-catalog" aria-label="Danh sách đánh giá">
    <div class="tabs"><a class="<?= $filter==='unanswered'?'active':'' ?>" href="<?= e(url('admin/reviews.php')) ?>">Chưa phản hồi</a><a class="<?= $filter==='all'?'active':'' ?>" href="<?= e(url('admin/reviews.php?filter=all')) ?>">Tất cả đánh giá</a></div>
    <div class="catalog-list-meta"><span><?= $total ?> đánh giá · Trang <?= $page ?> / <?= $totalPages ?></span></div>
    <div class="table-wrap catalog-table-scroll"><table class="catalog-table"><thead><tr><th>Khách hàng / kỳ ở</th><th>Đánh giá</th><th>Nhận xét</th><th>Trạng thái</th><th class="catalog-action-cell">Hành động</th></tr></thead><tbody>
    <?php foreach($reviews as $review):$bookingId=(int)$review['booking_id']; ?>
        <tr><td><span class="catalog-name"><?= e($review['full_name']) ?></span><span class="catalog-secondary"><?= e($review['room_name']) ?> · Đơn #<?= $bookingId ?></span><span class="catalog-secondary"><?= e(date('d/m/Y',strtotime($review['check_in']))) ?> → <?= e(date('d/m/Y',strtotime($review['check_out']))) ?></span></td><td><strong><?= (int)$review['rating'] ?> / 5</strong></td><td class="catalog-comment"><?= e(mb_strimwidth($review['comment'],0,110,'…')) ?></td><td><?php catalog_status($review['replied_at']===null?'Chưa phản hồi':'Đã phản hồi',$review['replied_at']!==null); ?></td><td><div class="catalog-row-actions"><?php catalog_action('eye','Xem đánh giá đơn #'.$bookingId,'#review-'.$bookingId);if($review['replied_at']===null)catalog_action('edit','Phản hồi đánh giá đơn #'.$bookingId,'#review-'.$bookingId); ?></div></td></tr>
    <?php endforeach; ?>
    <?php if(!$reviews): ?><tr class="catalog-empty"><td colspan="5"><?= $filter==='unanswered'?'Không có đánh giá đang chờ phản hồi.':'Chưa có đánh giá sau lưu trú.' ?></td></tr><?php endif; ?>
    </tbody></table></div>
    <?php foreach($reviews as $review):$bookingId=(int)$review['booking_id'];catalog_dialog_start('review-'.$bookingId,'Đánh giá của '.$review['full_name'],$review['rating'].' / 5 · '.$review['room_name'],$error!==''&&$replyBookingId===$bookingId); ?>
        <p class="catalog-summary-line">Đơn #<?= $bookingId ?> · <?= e(date('d/m/Y',strtotime($review['check_in']))) ?> → <?= e(date('d/m/Y',strtotime($review['check_out']))) ?></p>
        <p style="white-space:pre-wrap;overflow-wrap:anywhere"><?= e($review['comment']) ?></p><p class="catalog-note">Khách gửi lúc <?= e(date('d/m/Y H:i',strtotime($review['created_at']))) ?></p>
        <?php if($review['replied_at']!==null): ?><div class="notice"><strong>Phản hồi của khách sạn</strong><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?= e($review['admin_reply']) ?></p><small><?= e($review['responder']??'') ?> · <?= e(date('d/m/Y H:i',strtotime($review['replied_at']))) ?></small></div><div class="catalog-dialog-actions"><button type="button" class="button outline" data-close-dialog>Đóng</button></div>
        <?php else:if($replyBookingId===$bookingId)catalog_error($error); ?>
            <form method="post" action="<?= e(url('admin/reviews.php?filter='.$filter.'&page='.$page)) ?>"><?= csrf() ?><?php catalog_hidden(['booking_id'=>$bookingId]); ?><label>Phản hồi cho khách<textarea name="admin_reply" rows="4" maxlength="2000" required><?= e($replyBookingId===$bookingId?$replyText:'') ?></textarea></label><?php catalog_form_actions('Gửi phản hồi'); ?></form>
        <?php endif;catalog_dialog_end();endforeach; ?>
    <?php if($totalPages>1): ?><nav class="actions catalog-pager" aria-label="Phân trang đánh giá"><?php if($page>1): ?><a class="button outline" href="<?= e(url('admin/reviews.php?filter='.$filter.'&page='.($page-1))) ?>">← Trang trước</a><?php endif; ?><span>Trang <?= $page ?> / <?= $totalPages ?></span><?php if($page<$totalPages): ?><a class="button outline" href="<?= e(url('admin/reviews.php?filter='.$filter.'&page='.($page+1))) ?>">Trang sau →</a><?php endif; ?></nav><?php endif; ?>
</section><?php require __DIR__.'/../staff_footer.php'; ?>
